import sys
sys.setrecursionlimit(20000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, index):
    if index >= len(nodes) or nodes[index] == -1:
        return None
    root = Node(nodes[index])
    root.left = build_tree(nodes, 2 * index + 1)
    root.right = build_tree(nodes, 2 * index + 2)
    return root

def find_mirror(root, target):
    def dfs(node, depth, path_directions):
        if not node:
            return None
        if node.data == target:
            return (depth, path_directions)
        left_res = dfs(node.left, depth + 1, path_directions + ['L'])
        if left_res:
            return left_res
        right_res = dfs(node.right, depth + 1, path_directions + ['R'])
        if right_res:
            return right_res
        return None

    target_info = dfs(root, 0, [])
    if not target_info:
        return -1

    depth, path = target_info
    current = root
    for direction in path:
        if direction == 'L':
            current = current.right
        else:
            current = current.left
        if not current:
            return -1
    return current.data

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    nodes = []
    idx = 1
    for _ in range(n):
        nodes.append(int(input_data[idx]))
        idx += 1

    target = int(input_data[idx])

    root = build_tree(nodes, 0)
    result = find_mirror(root, target)
    print(result)

if __name__ == "__main__":
    main()
